printf '%s\n' 'import argparse' 'import json' '' 'parser = argparse.ArgumentParser()' 'parser.add_argument("config")' 'parser.add_argument("--env", choices=["dev", "staging", "prod"], default="dev")' 'args = parser.parse_args()' 'cfg = json.load(open(args.config))' 'merged = {**cfg["defaults"], **cfg.get("environments", {}).get(args.env, {})}' 'print(json.dumps(merged, indent=2, sort_keys=True))' > build_config.py
